import json, math, sys
data=json.load(open(sys.argv[1]))
def r6(x): return round(x*1e6)/1e6
H={}
def hyp(name):
    def deco(f):
        H[name]=f; return f
    return deco
@hyp('r6(L)')
def _(s,e):
    return r6(math.hypot(e[0]-s[0],e[1]-s[1]))
@hyp('r6 proj diff')
def _(s,e):
    L=math.hypot(e[0]-s[0],e[1]-s[1]); d=((e[0]-s[0])/L,(e[1]-s[1])/L)
    return r6(e[0]*d[0]+e[1]*d[1]) - r6(s[0]*d[0]+s[1]*d[1])
@hyp('m9*1000')
def _(s,e):
    L=math.hypot(e[0]/1000-s[0]/1000,e[1]/1000-s[1]/1000)
    return round(L*1e9)/1e9*1000
@hyp('sqrt r6 sq')
def _(s,e):
    dx=e[0]-s[0]; dy=e[1]-s[1]
    return math.sqrt(r6(dx*dx+dy*dy))
@hyp('r6(L)+0 via n*1e-6')
def _(s,e):
    return round(math.hypot(e[0]-s[0],e[1]-s[1])*1e6)*1e-6
res={k:0 for k in H}
for s,e,o in data:
    for k,f in H.items():
        if f(s,e)==o: res[k]+=1
print(len(data), res)
# show a few mismatches for r6(L)
n=0
for s,e,o in data:
    v=H['r6(L)'](s,e)
    if v!=o and n<15:
        n+=1
        print(s,e,repr(o),repr(v),(o-v)/math.ulp(v))

