try:
    v = json.loads(lines[-1])
    skip = {'category','guid','level','top_level','limit_offset','point','name','number'}
    for e in v['elements']:
        print({k: e[k] for k in sorted(e) if k not in skip}, e.get('point'))
except Exception as ex:
    print('ERR', ex, lines[-1:] if lines else '')
if p.stderr:
    print('STDERR:', p.stderr.decode()[:2000])
shutil.rmtree(d)

