    if var==0: return (-dy/L*h, dx/L*h)
    if var==1: return (-dy*h/L, dx*h/L)
    if var==2: return (-(dy/L)*h, (dx/L)*h)
    if var==3:
        f=h/L; return (-dy*f, dx*f)
res=[]
