"""keptf.py file [cmd...]: open file, run cmds, then freeze each enclosed room and print its kept loops."""
import os, sys, subprocess, json, tempfile, shutil
ORIG = '/workspace/executable'
f = sys.argv[1]; pre = sys.argv[2:]
def run(cmds):
    d = tempfile.mkdtemp(prefix='wk')
    shutil.copy(f, d)
    args = [ORIG, 'run', os.path.basename(f)]
    for c in cmds:
        args += ['--cmd', c]
    p = subprocess.run(args, cwd=d, capture_output=True, timeout=300)
    shutil.rmtree(d)
    lines = [l for l in p.stdout.decode().split('\n') if l.strip()]
    return lines, p.stderr.decode()
lines, err = run(pre + ['elements {"category":"room"}', 'room_area {"at":"finish"}', 'elements {"category":"room"}'])
if err: print('STDERR', err[:1000])
cen = json.loads(lines[-3])['elements']; fin = json.loads(lines[-1])['elements']
skip = {'category','guid','level','top_level','limit_offset','name','number','kept','frozen'}
for c, fe in zip(cen, fin):
    print('room', c['id'], 'pt', c['point'], 'centre:', c['area_m2'], c['perimeter_m'], 'finish:', fe['area_m2'], fe['perimeter_m'], {k: c[k] for k in c if k not in skip and k not in ('area_m2','perimeter_m','point','id')})
for c in cen:
    if not c.get('enclosed'): continue
    i = c['id']
    lines, err = run(pre + ['modify {"id":%d,"frozen":true}' % i, 'elements {"category":"room"}'])
    if err: print('STDERR', i, err[:300]); continue
    for e in json.loads(lines[-1])['elements']:
        if e['id'] == i:
            k = e.get('kept')
            print('kept', i)
            for mode in ('centre', 'finish'):
                if mode not in k: print('  ', mode, 'MISSING'); continue
                print('  ', mode, 'outer', k[mode]['outer'])
                for h in k[mode]['holes']:
                    print('  ', mode, 'hole ', h)

