import math
obs = [[-1.4997597826618578e-29, 0.0], [3.9465431434568927, -125.58103905862704], [15.77059737104446, -250.66646712860896], [35.42549854262256, -374.762629171449], [62.83367774273779, -497.3797743297095], [97.88696740969294, -618.0339887498949], [140.44702822349723, -736.2491053693561]]
mid = [2000.0000000000002, -1999.9999999999998]
last = [[3996.053456856543, -125.58103905862679], [4000.0, 0.0]]
s=(0.0,0.0); e=(4000.0,0.0); arc=180.0
n=50
th=math.radians(arc)
# centre: chord midpoint + perpendicular
cx, cy = 2000.0, 0.0
r=2000.0
def cand(k, form):
    if form==0:
        a = math.pi + k*th/n
        return (cx + r*math.cos(a), cy + r*math.sin(a))
    if form==1:
        a = math.pi + th*k/n
        return (cx + r*math.cos(a), cy + r*math.sin(a))
    if form==2:
        a0 = math.atan2(s[1]-cy, s[0]-cx)
        a = a0 + th*(k/n)
        return (cx + r*math.cos(a), cy + r*math.sin(a))
    if form==3:
        # rotate start vector
        a = th*k/n
        vx, vy = s[0]-cx, s[1]-cy
        c, si = math.cos(a), math.sin(a)
        return (cx + vx*c - vy*si, cy + vx*si + vy*c)
    if form==4:
        a = th*k/n
        vx, vy = s[0]-cx, s[1]-cy
        c, si = math.cos(a), math.sin(a)
        return (cx + (vx*c - vy*si), cy + (vx*si + vy*c))
for form in range(5):
    pts=[cand(k,form) for k in range(n+1)]
    ok=[tuple(p)==tuple(o) for p,o in zip(pts,obs)]
    print(form, ok, pts[1], pts[25]==tuple(mid), pts[25], pts[49], pts[50])

